import {monthlyGuidePlanLines,monthlyGuidePlanSummaries} from './monthly-content.mjs';
import {money,escapeHtml as e} from './shared.mjs';
import {researchGuideContent} from './research-guide-content.mjs';
import {researchGuideExpansions} from './research-guide-expansions.mjs';
import {longtailGuideContent} from './longtail-guide-content.mjs';
import {operatingGuideContent} from './operating-guide-content.mjs';
import {floridaGuideContent} from './florida-guide-content.mjs';
import {withFloridaGuideExamples} from './florida-guide-additions.mjs';
import {expandLongtailSections} from './longtail-guide-expansions.mjs';
import {careBoundary} from './offer-summary.mjs';
import {serviceCoverage} from './service-area.mjs';
import {guideReviewChoices} from './guide-practical-steps.mjs';
import {searchGuideAdditions} from './search-content.mjs';
import {p,a,link,section,richSection,ul,ol,box,worksheet,table,auditTable,download,sources,anchoredSection,disclosureSection,formatGuideSections} from './guide-content-helpers.mjs';

// Authoritative final section definitions, in reading order. Offer values are
// evaluated from the caller's current configuration on every render.
const guideContent={
 "/guides/website-maintenance-cost/":o=>[
  richSection('three-bills','Budget for three different jobs',p('Website maintenance cost depends on who operates the platform, who checks the customer journey and who makes changes. Start with three lines: provider bills, routine care and improvement work. A low hosting bill can be perfectly sensible, but it does not tell you whether anyone checks your form or updates your opening hours.')+ul(['Provider bills keep accounts and tools available: domain renewal, hosting, business email and any paid booking or newsletter service.','Routine care checks the website and makes small updates within a stated allowance. Ask who notices an outage and who follows it up.','Improvement work changes the content or experience: a clearer service page, an article or a better inquiry journey. Budget this separately when the care plan does not include it.'])+p('A static brochure site, a CMS with several editors and a store have different moving parts. Write down the actual tools before comparing monthly fees.')),
  section('platform-cost','Check the provider bills',p('List your domain renewal, hosting, email and paid form, booking or newsletter tools. Check the billing interval, renewal price and account owner. A free plan may have limits; paying a provider does not include someone checking your form or updating the website.')),
  richSection('studio-plans','What my monthly plans pay for',auditTable('Monthly studio plans — USD',['Plan','Monthly price','Work included'],monthlyGuidePlanSummaries(o).map(plan=>[e(plan.name),money(plan.price),e(plan.work)]))+careBoundary()+p('An improvement is a finished task, such as rewriting a service page. See '+a('/services/website-care/','care limits')+' and '+a('/services/seo/','Improve and Grow limits')+'.')),
  richSection('first-year','Work out a first-year budget',auditTable('Illustrative first year of care on an existing site',['Cost','Amount'],[
   [o.plans.keep_running.public_name+': 12 monthly cycles',money(o.plans.keep_running.monthly_price*12)],[o.baseline.public_name+' (one-time, if needed)',money(o.baseline.one_time_price)],['Hosting: assumed $20 × 12 months','$240'],['Other provider bills: assumed yearly total','$120'],['Example total before tax',money(o.plans.keep_running.monthly_price*12+o.baseline.one_time_price+360)]
  ])+box('When the Baseline is needed',p(`Monthly care on an existing website starts with the one-time ${money(o.baseline.one_time_price)} Website Baseline unless a previous Website Baseline, studio build or Audit &amp; Fix Sprint still provides a current, usable review. Work already included in a build is not sold again as monthly care.`))+p('These hosting and other-bill figures are planning assumptions, not typical market prices or provider quotes. Replace them with your real domain, email, hosting and tool renewals. The example uses twelve monthly invoices; monthly service is optional.')+p(a('/assets/guides/website-maintenance-budget.csv','Download the maintenance budget worksheet'))),
  richSection('checks','Ask what gets checked and how recovery works',ul(['Does the public domain load over HTTPS, and is the certificate valid? Record the date and the person who follows up on an alert.','Can a permitted test inquiry be submitted, found at its receiving destination and replied to? A green form message alone is not enough.','Which CMS, plugins and external tools need updates, and who tests the affected pages afterward? A static site may have a different update process.','What is backed up: files, content, database and settings? Arrange a recovery test on a separate copy with your web person.','Who owns Search Console, domain recovery and vendor billing? Check access before the only administrator leaves.'])+p(`${a(sources.backups,'WordPress’s backup guidance')} distinguishes database and file backups. Other platforms have different export and recovery limits; confirm yours. A successful export is useful evidence, but a recovery test establishes whether the site can actually be restored.`)),
  richSection('choose-care','Choose the help you need',p('If the site works and you can own its checks, you may only need provider subscriptions and occasional help. If small updates and routine checks are repeatedly missed, care may fit. Choose an improvement plan when you have content or customer-journey work ready to approve; choose a review when the cause of a problem is still unclear.')+p(`Compare the ${a('/services/website-audit/',money(o.baseline.one_time_price)+' Website Baseline and '+money(o.audit_sprint.one_time_price)+' Audit &amp; Fix Sprint')}: both review up to ${o.baseline.page_cap} agreed main pages on one website, with larger sites quoted separately.`))
 ],
 "/guides/website-launch-checklist/":o=>[
  anchoredSection(['launch-check-tools'],richSection('release-record','Start with one version and one decision maker',p('A launch checklist should answer a practical question: can a customer use this version, and can the owner operate it afterward? Write down the preview link or version, public website address, approver and launch date. Keep a short list of unresolved issues with an owner for each. “Looks good” is not a useful launch record. Note the version, approver, date and checks.')+p('Use Not checked, Works, Needs fixing, Need access, Not applicable or Blocked. Explain any blocked check and who can resolve it. Keep the preview site hidden from Google until you approve going live.')+p(a('/assets/guides/website-launch-checklist.csv','Download the website launch checklist')))),
  richSection('content-approval','Approve the facts customers act on',ul(['Read the main service page aloud. Can a new visitor tell what is offered, where it is available and how to start?','Verify prices, opening hours, service boundaries and response expectations with the business owner.','Check project images, testimonials and credentials against permission and actual evidence. Remove placeholders.','Open policy links and downloads. Confirm the contact details and the person responsible for inquiries.','Confirm image descriptions convey relevant meaning and decorative images do not repeat surrounding text.'])+p('For a contractor, a project photo needs an accurate description of the work shown. For a consultant, the inquiry should ask for the information needed to assess fit. The check is about this business, not filling every available section of a template.')),
  section('customer-journey','Check forms and connected tools','<p>Follow the <a href="/guides/contact-form-not-working/">contact-form test</a> from submission to reply. Open booking and other connected tools on a phone. Confirm the right person receives requests and knows what to do next.</p>'),
  section('accounts-search','Confirm your account access','<p>Check that you can sign in to the domain, hosting and included tools yourself, and that the recovery contacts are current. Keep control of these accounts throughout the project.</p>'),
  richSection('recovery','Know how to recover before the switch',p('Keep the approved source, content and configuration needed to restore the prior version. Name the person who can restore the previous version and the condition that would trigger it, such as a broken inquiry path. Check what the host can restore and what lives in a separate service. Do not assume a website backup also contains mailbox, booking or newsletter data.')+p('A launch record should name the published version, date, approver, checks and unresolved items. On a redesign, attach the '+a('/guides/website-migration-checklist/','old-to-new URL map')+'.')),
  section('live-check','Recheck the live site','<p>Open the public website outside the preview session. Check the main pages, a useful old URL, a download and a missing URL. Repeat the <a href="/guides/contact-form-not-working/">form test</a>. Record the result and who will handle any remaining issue. For a replacement website, keep the <a href="/guides/website-migration-checklist/">migration checklist</a> with your launch notes.</p>'),
  disclosureSection('developer-launch-checks','For your web person','Technical checks before and after launch',[richSection('technical-release','Check the intended public version',p('Verify HTTPS, preferred domain, titles, descriptions, canonical URLs, sitemap, indexing instructions, redirects and the missing-page response. Keep private previews out of search. Preserve unrelated email DNS settings. Record Search Console access and inspect intended public URLs after launch; a live test does not guarantee indexing.'))])

 ],
 "/guides/ai-website-or-custom/":o=>[
  richSection('choose-the-job','Start with the work the website must do',p('An AI website builder can help turn a short brief into a first draft of a layout and copy. A custom project can put more attention into the service story, visual direction and connected customer journey. Either can be a reasonable starting point. Neither removes the need to check the facts, test the form and decide who maintains the result.')+p('“AI” describes a tool or method; “custom” describes how closely the work is shaped around your requirements. They can overlap. A designer may use AI during a custom project, and an owner may refine a builder draft with expert help. Compare the finished responsibilities and handoff.')),
  richSection('comparison','Compare the same brief in each approach',auditTable('Questions for an AI builder and a custom project',['Decision','Builder-led approach','Custom project'],[
   ['Content','Who corrects generated service claims, prices and location details?','Who interviews the owner, drafts the pages and obtains factual approval?'],
   ['Design','Can the editor support the layout and brand changes you need?','Which original design decisions are included, and how many review rounds?'],
   ['Functions','Does the selected plan support the real form, booking or store task?','Which connections are configured and tested within the signed scope?'],
   ['Editing','Can the owner make a routine change without breaking the layout?','Is editing through a CMS, technical source or a maintenance service?'],
   ['Ownership','What can be exported, and what requires the platform to keep running?','Which paid source and assets are handed over, and which licenses remain?'],
   ['Cost','What are the subscription, renewal, add-on and usage costs?','What are the build fee, provider bills and optional ongoing work?']
  ])+p('A subscription comparison is not a total project comparison. Include the owner’s time for writing, media selection, checking and ongoing edits. Use the '+a('/guides/website-project-cost/','website cost guide')+' to put both options on the same basis.')),
  section('trial', 'Test the generated draft before buying more work', `<p>Try a short, factual brief: “Create a draft website for a Buffalo garden-care business. Use these approved services and coverage details. Leave missing prices, credentials and project examples blank. Make the main action a request for an estimate.” Supply only information you have permission to use.</p>${ol(['Check whether the tool invented a review, qualification, address or completed project. Remove each unsupported claim.', 'Replace a service paragraph and one image. Check the phone layout and whether you can undo the change.', 'Test the full form with a controlled address, then inspect where the message arrived and whether you can reply.', 'Ask what can be exported, how backups work and which features stop when the subscription ends.'])}<p>Use ${link('/assets/guides/website-approach.csv', 'the approach comparison worksheet')} to record the results. If the design structure itself is the question, use ${link('/guides/custom-website-or-template/', 'the separate custom-versus-template guide')}.</p>`),
  richSection('review-ai-copy','Review generated copy like any other draft',p('Check every service claim against the business’s actual work. Look for invented years of experience, credentials, client names, project results and locations. Replace vague claims with specific approved facts: what you do, what you need from a customer and what happens after an inquiry.')+p(`Google’s ${a(sources.aiContent,'guidance on generative AI content')} allows room for AI as a research and structuring aid, while emphasizing accurate, relevant content and warning against producing many pages without value for users. A page that only swaps the town name adds little; add a separate area page only when its advice, evidence or service detail substantially helps the visitor.`)+p('Keep a named human approver for business claims. A generated project image should not be presented as a photograph of completed customer work. Review licenses and the tool’s actual terms for the assets you intend to publish.')),
  richSection('ai-search','Being built with AI does not buy AI-search visibility',p(`Google says its ${a(sources.aiSearch,'AI Overviews and AI Mode guidance')} follows the same core search practices: make the site accessible to crawling, provide helpful content, and meet the requirements for eligible pages. It does not require special AI markup or an extra machine-readable AI file to appear in those features. Inclusion is not guaranteed.`)+p('The practical task is still to explain the real service, support claims, use clear internal links and keep the information current. Ask any provider selling an AI-search service what they will change and what evidence they can report. A builder’s AI label is not evidence of visibility.')),
  richSection('custom-fit','When a studio project is worth discussing',p(`My ${e(o.launch_site.public_name)} package is ${money(o.launch_site.public_price)} for up to ${o.launch_site.marketing_page_cap} marketing pages; ${e(o.focused_site.public_name)} is ${money(o.focused_site.public_price)} for up to ${o.focused_site.marketing_page_cap}; Signature is ${money(o.signature_site.public_price)} for up to ${o.signature_site.marketing_page_cap}. Page counts are scope limits. My builds have no drag-and-drop editor. Changes require coding skills, a developer or optional care. If you want to edit pages yourself every week, a builder may suit you better. Editing, connected tools and creative needs should drive the choice. Read the ${a('/pricing/','complete package inclusions')} before comparing a quote.`))
 ],
 "/guides/website-not-showing-on-google/":o=>[
  anchoredSection(['discovery'],richSection('define','Describe what is missing',p('Write down the page address, search phrase, date and result you expected. Is a new page absent, did an older page disappear after a redesign, or does a service search show other businesses? ')+ul(['Follow a normal link to the page from your own website. Check that it opens without a login or error.','Note any recent launch, page-address change or access change.','For a moved page, compare the old and new address using the '+a('/guides/website-migration-checklist/','migration checklist')+'.'])+worksheet('google-visibility-flow','Download the search-visibility worksheet'))),
  richSection('plain-search-terms','Four terms used in these checks',ul(['<strong>Search Console:</strong> Google’s free tool showing how it finds and lists your website.','<strong>Indexed:</strong> stored by Google so a page can appear in search results. A <strong>crawl</strong> is Google’s robot visiting a page.','<strong>Canonical:</strong> the preferred page address when similar versions exist.','<strong>Noindex:</strong> an instruction to leave a page out of search. Use it for unfinished pages that should stay out of search; protect private material with sign-in or other access controls.'])+p('No one can promise a Google position; these steps help you find and fix what you can control.')),
  anchoredSection(['index','intent'],section('inspection-steps','Run your first Search Console check',p('Open the page in a private browser window. If it is a preview or not ready yet, leave it hidden and ask your web person before changing that. If you cannot access Search Console, ask the domain owner to add you or send you this page’s URL Inspection result.')+ol(['Open the correct website in Search Console. Paste the full public page address into the inspection bar.','Read whether Google has indexed the page. If it has not, note the reported reason and the last crawl date.','Choose Test live URL to check the current page. Compare it with the earlier indexed result: a recent fix may not appear in the older record.','After the problem is fixed and the page is ready for the public, use Request indexing once.'])+p(a(sources.inspection,'Google’s URL Inspection instructions')+' show the current controls.'))),
  richSection('specific-index-checks','Use the reported reason to choose the next check',auditTable('Search Console findings and next checks',['Finding','What to do next'],[
   ['Excluded by noindex','If this page should be public, ask your web person to remove the noindex setting from the page and server.'],
   ['Blocked by robots.txt','Ask your web person whether a rule stops Google visiting this page. Keep deliberate restrictions on private previews.'],
   ['Page with redirect','Check that the destination is the intended replacement.'],
   ['Alternate page with proper canonical tag','Usually no change is needed if this is an intended duplicate and the preferred page is correct.'],
   ['Duplicate, Google chose different canonical than user','Compare Google’s chosen page with your preferred page. Ask your web person to investigate if the choice is wrong.'],
   ['Not found (404)','Restore the page if it should exist, or redirect it to a relevant replacement. An intentionally removed page with no replacement may remain missing.'],
   ['Server error (5xx)','Ask your web person or host to investigate why the server could not return the page.'],
   ['Discovered — currently not indexed','Google knows the address but has not visited it yet. Check that visitors can reach it from another page on your website.'],
   ['Crawled — currently not indexed','Google has visited but has not listed it. Review whether it answers a useful question or mostly repeats another page.']
  ])+p('These are plain next-step explanations of the report labels. Keep the result and date with your notes. The '+a(sources.indexing,'Page indexing report guide')+' explains these reasons.')),
  richSection('relevance','Check whether the page answers the search',p('If Google has indexed the page, review the question you want it to answer. Does the page explain the service, who it is for, where it is available and how to start? Replace general promises with useful business facts.')+p('In Search Console, compare searches and pages over a stated period. Choose one useful improvement and record the date. Keep search clicks and real inquiries as separate counts; the '+a('/guides/seo-work-and-reporting/','SEO reporting guide')+' shows how to review both.')),
  richSection('maps','Treat Maps as a separate question',p('A Google Business Profile has its own '+a('/guides/local-seo-profile-eligibility/','eligibility rules')+'. Check how customers actually meet the business before changing a profile. An online business can explain its service area without inventing an office.')),
  disclosureSection('technical-search-checks','For your web person','Access, indexing instructions and page addresses',[
   richSection('response-checks','Check the actual public response',p('Inspect the HTTP response, HTML robots directive and X-Robots-Tag header on the intended public URL. Distinguish robots.txt crawling restrictions from noindex. Preserve private-preview controls. Compare the selected canonical, redirect destination, sitemap and internal links with the intended page map.')+p('Use a live inspection alongside the last recorded crawl. Search Console’s Performance report answers query-visibility questions; Analytics visits do not establish indexing. See '+a('https://developers.google.com/search/docs/essentials/technical','Google’s technical requirements')+'.'))
  ])
 ],
 "/guides/contact-form-not-working/":o=>[
  anchoredSection(['trace','inbox'],richSection('five-minute-check','Start with one labeled test',p('Use made-up details and an email address you control. Never share passwords or customer records when asking for help.')+ol(['Open the public form, fill it in and send one message labeled “Website test” with the time. Note what the page says.','If your form tool saves submissions, look for that same test there.','Check who receives the form’s email notifications. Search that inbox and its spam folder.','Reply to the test email and check that the reply reaches your test address.','If a step fails, send your web person the page address, time and what happened. If you do not have one, the help options below explain how I can trace it.'])+worksheet('contact-form-flow','Download the form test checklist'))),
  richSection('page','Check what the visitor can do',p('Open the public page on a phone and on the device where the problem was reported. Can you reach every field and press Send? Try leaving a required field empty, then correct it. The error should explain what is missing and preserve the details already entered.')+ul(['Note any field error or spam-check message.','Check whether a loading message finishes or stays stuck.','Record the exact confirmation or error and the test time.'])+p('If the button never sends the form, show that step to your web person before changing inbox settings.')),
  section('platform-settings','Check the form’s notification settings',`<p><strong>Squarespace:</strong> open the form’s storage and email settings, confirm the receiving address, and check the connected storage if you use it. ${link('https://support.squarespace.com/hc/en-us/articles/205813938-Troubleshooting-form-issues','Squarespace’s form troubleshooting guide')} explains the current settings and account limits.</p><p><strong>Wix:</strong> in the site dashboard, open Automations and find the automation for this form. Check that it is on and look at its email history, then open the email step and check who receives it. Add anyone outside your site collaborators as a Wix contact before choosing them as a recipient. Changing your account email may not change an existing automation’s recipient. ${link('https://support.wix.com/en/article/wix-forms-choosing-who-gets-notified-about-form-submissions','Wix’s notification guide')} shows the current controls. Log out and send another test.</p><p><strong>WordPress:</strong> identify the form plugin, then check that form’s recipient and available mail log. Give your web person the plugin name and the failed step before adding another mail plugin.</p>`),
  richSection('verify','Retest and keep a short record',p('After the fix, repeat the same submission-to-reply test. Try the affected phone or browser again. Write down what worked and anything you could not check, such as an account you cannot access. Delete your test messages when you are done.')+p('Keep the original problem, the change, the date and the result together. A saved submission and an email arriving are separate steps; record both when the platform supports them.')),
  section('review-options','Want me to fix it?',p(`For one broken form, start by asking about the ${link('/services/website-audit/#offer-website_baseline',money(o.baseline.one_time_price)+' Website Baseline')}. It reviews the site, and its small first fix can be the form when safe and practical. The ${link('/services/website-audit/#offer-audit_fix_sprint',money(o.audit_sprint.one_time_price)+' Audit &amp; Fix Sprint')} includes the review and up to two small fixes in total.`)+p(`Both cover up to ${o.baseline.page_cap} agreed main pages on one website; larger sites are quoted separately. Before you pay, I check your platform and the access I need. On Wix, access is through a collaborator invitation.`)),
  disclosureSection('specific-form-checks','For your web person','Trace receiving-system and email-delivery failures',[
   richSection('receipt','Confirm that the receiving system accepted it',p('Ask the person managing the form to look for the same test in the system that receives inquiries. Depending on the setup, that evidence might be a stored record, submission identifier or provider receipt. A site may not store a separate inquiry record; document the actual design instead of assuming that every form has a database.')+p('If the browser reports success but the operator cannot establish receipt, capture both observations. Ask your web person to check the submission response and the agreed receiving destination. Request a finding with private details removed and a clear next action.')+p('Illustrative example: the test appears in a saved submission record, but no notification is found. That narrows the investigation to the later delivery stages. It does not prove the form lost the inquiry or that a different website platform is required.')),
   richSection('notification','Check the notification attempt',p('Once receipt is established, find out whether the system attempted to notify the intended business address. Confirm the destination spelling and whether an old employee, former provider or test mailbox still receives the messages. Review the notification status through authorized tools if those tools provide one.')+p('Distinguish a notification being requested from it being accepted by an email service, and distinguish both from arrival in the reader’s inbox. Record the status shown, rather than translating an unfamiliar provider label into “delivered.” If the service reports rejection or a delay, give that exact redacted finding to the web person.')+p('The next technical check depends on the system in use. Sender configuration, allowed destinations, service limits or an expired connection may warrant investigation, but this checklist cannot identify one of them without evidence. Make one agreed change, keep a recovery route and repeat the same test.')),
   richSection('specific-form-checks','Match the symptom to a concrete check',auditTable('Contact-form symptoms, checks and next actions',['Symptom','Check','Next action'],[
   ['Submit does nothing','Check visible field errors and whether the CAPTCHA loads. Try a fresh session on the actual public domain.','Record browser, URL and time. Ask your web person to inspect script/network errors and the configured challenge hostname.'],
   ['Challenge keeps failing','Record the displayed error code; a changed hostname or expired challenge can require different action.','Use the provider’s error guidance. Do not disable spam protection to make a test pass.'],
   ['Success appears, but no inquiry is found','Check the form provider’s submission record and the server response, using authorized access.','Confirm whether it was stored before investigating email. A success message can be misleading if the application handles errors incorrectly.'],
   ['Record saved, email missing','Check the current destination, notification log, sender settings, quotas and any expired email connection.','Correct the evidenced failure and repeat the same labeled test. On WordPress, identify the configured mail path before adding an SMTP plugin.'],
   ['Email goes to spam or bounces','Inspect the redacted rejection reason and sender authentication result.','Ask your mail administrator to check SPF, DKIM and DMARC: domain settings that help receiving mail services verify who sent a message. Do not change these records yourself without qualified help.'],
   ['Reply goes to the wrong address','Inspect the controlled test message’s Reply-To value.','Use the verified business sender for From and the validated customer address for Reply-To where supported; retest the reply.']
  ])+p(`For Turnstile, ${a(sources.challenge,'Cloudflare’s error-code reference')} distinguishes invalid configuration, unauthorized hostnames and expired challenges. ${a(sources.email,'Google’s email sender guidelines')} explain authentication requirements for mail sent to Gmail. An authentication pass can help delivery, but does not prove inbox arrival.`)+p('Give support the URL, time, test reference, failed stage and redacted error. '))
  ])
 ],
 "/guides/service-area-pages/":o=>[
  richSection('question','Begin with a customer decision',p('A service-area page should help someone decide whether and how a business can serve them. A place name alone does not answer that question. Before writing, identify the useful decision: availability at an address, remote versus on-site delivery, the relevant service, or information needed for a quote.')+p('Listing the towns you serve is different from making a page for each town. A list can reassure a visitor that their community is within the intended area. It does not automatically justify a new page for each place. For a small service business, one clear service page and an accurate coverage explanation may answer more questions than many nearly identical pages.')+worksheet('service-area-decision','Download the service-area planning worksheet')),
  richSection('facts','Confirm what your business actually does',p('Write down your services, how you deliver them and the places you actually cover before drafting a local page. Record whether work happens online, at the customer’s property or at a genuine business location. Identify any address-level assessment, travel charge or scheduling condition that customers need to understand; leave unknown conditions unresolved until the business supplies them.')+ul(['Which of your services are available here, and which are not?','What should a customer send you to request a quote?','Is there a genuine local difference that changes the decision?','Who will update your pages when coverage changes?'])+p('Do not convert service reach into an office claim. A business can explain remote delivery to customers in a place without saying it has premises there. Business Profile eligibility is a separate question covered in the '+a('/guides/local-seo-profile-eligibility/','local SEO and profile guide')+'.')),
  richSection('choose','Choose the smallest useful page structure',p('Use an existing service or coverage page when it already answers the visitor’s needs. A separate area page can help when it provides substantial additional planning advice, evidence or maintained service information, even when the underlying service and prices are shared. A local example can support that explanation, but its presence alone does not justify another page. There is no useful minimum city count or required number of location pages.')+p('For example, an established service may have different booking requirements in a particular area. If those requirements are real, meaningful and maintained, they may warrant a separate explanation. A worked planning example can also add useful help without a difference in service availability. Assess its complete explanation and practical use. A paragraph about a landmark, a stock photograph and the same contact button do not establish that value.')+p('Google’s '+a('https://developers.google.com/search/docs/essentials/spam-policies','search spam policies')+' treat low-value town pages created only to manipulate search results, and search-targeted lists of place names, as spam. Compare the whole page with existing alternatives, combine pages that add no useful answer, and keep local details useful to customers.')),
  richSection('example','Work through an illustrative example',p('Imagine a fictional exterior-cleaning business that serves several nearby communities. Its actual quote process requires photographs, the surface type and access details. If those requirements are the same everywhere, one cleaning-service page can explain them and link to a coverage section. Repeating that page with a different town heading adds little to the quote decision.')+p('Now suppose the owner supplies a verified difference: one service is offered only within a smaller route area on stated days. The useful addition is a clear explanation of that service’s actual availability and how a customer checks their address. It may fit as a section on the service page. A separate page is an option only if there is enough distinct information to help the visitor.')+p('This is a fictional planning example, not a studio client, service recommendation or statement about local operating conditions. Any real business must supply its own coverage and booking facts.')),
  richSection('build','Write the page around the next action',p('Start with the service and the audience. Explain delivery, relevant boundaries, what the customer needs to provide and what happens next. Use actual evidence where available: an approved explanation of the process or a real project you have permission to show. If no local project evidence exists, describe the process plainly instead of inventing a case study.')+p('Connect the page to the main service, pricing or quote explanation and a relevant contact step. A reader should be able to move between the detailed service and its coverage without starting again from the homepage. Use descriptive links that explain the destination; repeating a service-and-city phrase in every link does not make the route easier to understand.')+p('For a new site, agree these page purposes in the '+a('/guides/website-redesign-brief/','website brief')+'. For an existing site with overlapping local pages, inventory their useful content and URLs before consolidating anything; the '+a('/guides/website-migration-checklist/','migration checklist')+' explains why redirect decisions need a plan.')+p(`If a useful new page goes beyond your package, an ${a('/services/website-addons/#addon-standard_page','additional standard page')} is ${money(o.add_ons.find(item=>item.id==='standard_page').public_price)}. The ${money(o.add_ons.find(item=>item.id==='three_page_bundle').public_price)} three-page bundle covers three related additional pages; it is not a reason to publish near-identical town pages.`)),
  richSection('maintain','Keep the coverage honest and current',p('I am based in Buffalo and work online with businesses across '+e(serviceCoverage().region)+'. My service-area pages combine the same remote service and prices with public business examples developed into website-planning briefs. The examples are not clients or completed studio work, and the advice can be useful beyond the named area. Their value comes from the practical explanation, not the county name. Your own coverage page should describe how you actually serve customers.')+p('Review your own coverage when services, staffing or booking conditions change. Record the owner’s confirmation and the pages affected. Use available search and inquiry information to find unanswered customer questions, rather than treating every keyword variation as a publishing instruction.')+p('The next step may be one better service section, a clearer county page or a separate page with substantial additional help. '+a('/services/seo/','SEO research and implemented website improvements')+' can help decide which change is useful. Measure what happens after the work, and keep outcomes separate from the fact that a page was published.'))
 ],
 "/guides/website-maintenance-checklist/":o=>[
  anchoredSection(['receipt'],section('start','Choose who checks the website',p('Write down the domain, hosting, form, booking tool and any other service the website uses. Name who can access each account and who handles a problem. Keep passwords and customer messages out of the checklist.')+p('Use the '+a('/assets/guides/website-maintenance-log.csv','website maintenance log')+' to record what should happen, what happened, the next action and the retest.'))),
  section('schedule','Set a useful schedule',table('A starting schedule to adapt',['When','Check'],[
   ['After a change','The changed page or tool and its main customer task.'],['Monthly','Key pages, contact and booking routes, and current business details.'],['Every 3 months','Account access, recovery arrangements and unresolved issues.'],['Before renewals','Who pays, the renewal date, price and payment details.']
  ])+p('A busy store or booking service may need more frequent checks and specialist help. Name the person and the frequency instead of relying on a reminder alone.')),
  anchoredSection(['forms','monthly-record'],section('content','The monthly checklist',ul(['<strong>Contact:</strong> send one labeled test from your phone, check that it reaches the right inbox and reply. If something fails, follow the '+a('/guides/contact-form-not-working/','form troubleshooting guide')+'.','<strong>Business details:</strong> check services, coverage, hours, prices and expired offers.','<strong>Links and downloads:</strong> open important buttons, booking links and useful files.','<strong>Phone and keyboard:</strong> try the main customer task without a mouse and on a narrow screen. Check field labels, errors and the visible keyboard focus.','<strong>Accounts:</strong> confirm someone can sign in and receives renewal notices. Do not put credentials in the log.','<strong>Follow-up:</strong> record Works, Needs fixing or Need access; assign the next action and retest after changes.'])+p('Keep small supplied edits together. A new service, major rewrite or new application needs its own plan.'))),
  section('recovery','Arrange software updates and recovery',p(`For a supported website with the access I need, ${a('/services/website-care/','Keep Running')} is ${money(o.plans.keep_running.monthly_price)}/month. It includes the checks listed in the plan and one set of small text, photo or link edits you send. An existing site first needs a current, usable review; the ${money(o.baseline.one_time_price)} Website Baseline is separate when needed. The broader recovery and software tasks below need their own responsible provider.`)+p('Ask your host or web person who updates the website software and who handles backups, restores and security incidents. Before a major change, ask them to identify the previous working version and explain how they would restore it. A downloaded copy and a tested restore are different checks.')+p('My monthly care plans exclude CMS, plugin and theme updates, backups, restores and malware cleanup. Monitoring is automated and is not staffed 24/7. Check '+a('/services/website-care/','care plan coverage')+' before deciding who will do each job.')+p('If you change providers, use the '+a('/guides/website-handover-checklist/','handover checklist')+' to keep account access and responsibilities clear.'))
 ],
 "/guides/contractor-website-checklist/":o=>[
  section('job','Tell customers which jobs you take',p('A contractor website should help a visitor decide whether the business does the work they need, serves their location and has a sensible way to assess the request. More traffic does not resolve an unclear offer or an inquiry form the team cannot use. Start with those decisions before adding pages or choosing an SEO campaign.')+p('List your trades or services, the jobs you accept, the jobs you turn down and how a customer starts. A business taking planned remodeling projects should not accidentally imply emergency repairs. A firm accepting commercial work should explain that distinction rather than relying on a photograph to communicate it.')+p(`The ${a('/assets/guides/contractor-website-worksheet.csv','contractor website worksheet')} connects each service with evidence, coverage, inquiry fields and a completion check. Use it to prepare a real brief; the example row is fictional.`)),
  section('services','Give each service a useful answer',p('A service page earns its place when a customer needs a distinct explanation. Describe the work included, suitable projects, dependencies and what happens before a quote or appointment. Closely related words can often share one page when they describe the same service and decision.')+ul(['Name the work in language customers use and the team can support.','Explain what information is needed to assess a request.','Identify any site visit, consultation or review required before pricing.','Use approved process details instead of promises about speed or availability.','Link related services and the actual inquiry route.'])+p('A county or town name is useful when it clarifies coverage. Repeating the same service copy across many town pages adds little for the visitor. Create a distinct location page only when there is substantial, accurate information that belongs there.')),
  section('evidence','Show real work with permission',p('Project photographs and short explanations can help a customer understand the work. Obtain the necessary permission and rights, identify what the business actually did and remove private customer details. A concise example can name the problem, scope, constraints and completed work without inventing a performance result.')+p('Keep professional credentials, insurance statements, memberships and reviews accurate and current. Publish them only when the business has supplied and approved the supporting facts. Do not create testimonials or imply that an illustrative design is a completed customer project.')+p('For a new business without suitable project examples, use a clear service explanation and an honest process. A labeled illustration can explain how work is planned, but it should remain visibly distinct from evidence of completed jobs.')),
  section('coverage','Explain where and how you work',p('State where you take jobs and what the customer needs to confirm. Explain any real limits involving job type, travel or scheduling. A travel area, a business address and online communication describe different arrangements.')+p('Use the '+a('/guides/service-area-pages/','service-area page guide')+' to decide whether one coverage section is enough or another page adds substantial advice, evidence or service information.')),
  section('inquiry','Ask for the information needed to respond',p('Choose fields with the person who handles estimates: service, job location, a short description, contact details and useful timing. Say what happens next. An estimate request is not a confirmed price, appointment or accepted job.')+p('Test the request on a phone and confirm it reaches the person who replies. If it fails, use the '+a('/guides/contact-form-not-working/','form troubleshooting guide')+'. Ask about photo uploads, quoting tools or customer portals separately; they add storage, access and support responsibilities.')+p(`If you need a separate request path with conditional questions, the ${a('/services/website-addons/#addon-guided_quote_form','guided quote-request form')} is ${money(o.add_ons.find(x=>x.id==='guided_quote_form').public_price)} for the listed work. It gathers information for a human quote; it does not calculate job prices. Use your included simple forms first.`)),
  anchoredSection(['local-seo-workflow'],section('search','Then work on search (SEO)',ol(['Give each genuinely different service a useful page.','State the real service area and add a separate area page only when its full content provides substantial additional help.','Make the estimate route work on a phone and check that requests arrive.','Check '+a('/guides/local-seo-profile-eligibility/','Google Business Profile eligibility')+' before adding or changing a profile.'])+p('Keyword tools estimate how often people search a phrase. Low numbers do not mean nobody asks, so use real customer questions too. Improve the page that answers the question, then review relevant search traffic and inquiries. For a new site, '+a('/services/contractor-websites/','see contractor website packages and the sample page plan')+'.')))

 ],
 "/guides/website-project-cost/":o=>[
  anchoredSection(['start-with-scope'],section('dated-price-example','Fixed prices and payment stages',table('Current studio website prices',['Package','Build fee','Page limit'],['launch_site','focused_site','signature_site'].map(id=>[link('/pricing/#offer-'+id,o[id].public_name),money(o[id].public_price),`Up to ${o[id].marketing_page_cap} pages`]))+p(`Payment is 50% at booking, 30% when you approve the design and 20% when you approve the finished site, before launch. For Launch: ${money(o.launch_site.public_price*.5)} / ${money(o.launch_site.public_price*.3)} / ${money(o.launch_site.public_price*.2)}.`)+'<span id="annual-choice"></span><span id="payment-schedule"></span>'+p('Comparing with a do-it-yourself builder? Add its yearly plan, domain, paid add-ons and the hours you would spend writing and building. These are my package prices; a provider subscription pays for a different part of the job.'))),
  section('two-budgets','What each build includes',p('Every package includes writing, keyword research, on-site SEO, design, two review rounds (one on the design and one on the finished website), launch checks, source files, written handoff instructions and an optional handoff call of up to 30 minutes. You control the accounts. One initial launch is included. For 30 days after launch, I correct anything I built that does not work as agreed, at no extra charge.')+p('Launch includes one contact form and one ready booking or email-signup link or compatible standard embed. Setting up the outside account is separate. Focused adds more service detail, two forms, two original guides and up to two ready connections. Signature adds a larger page plan, four original guides and one original animated homepage feature or one 3D centerpiece. Guides count within the page limit.')+p('My builds have no drag-and-drop editor. Changes require coding skills, a developer or optional care. See '+a('/pricing/#website-packages','the full package comparison')+' before choosing.')),
  anchoredSection(['scope-changers'],section('optional-additions','Budget for extra work only when you need it',p('Use the pages, forms and connections included in your package first. More pages, extra review rounds, a new design direction or a complex connection need a written price before work starts.')+table('Examples of additional website work',['Extra work','One-time fee'],['standard_page','three_page_bundle','contact_form','guided_quote_form','job_dashboard','client_portal'].map(id=>{const item=o.add_ons.find(x=>x.id===id);return [a('/services/website-addons/#addon-'+id,item.public_name),money(item.public_price)];}))+p('The '+a('/services/website-addons/','add-on guide')+' lists the limits for each extra. Original photography and a full brand identity need their own proposal. The listed custom inquiry/job dashboard and client portal have defined scopes; tools beyond those limits need a separate quote.'))),
  section('ongoing-costs','Add the first year’s continuing bills',p(`Monthly help is optional: Keep Running ${money(o.plans.keep_running.monthly_price)}, Improve ${money(o.plans.improve.monthly_price)} or Grow ${money(o.plans.grow.monthly_price)}. You pay hosting, domain, email and other tools directly to their providers.`)+table('Illustrative first-year budget — replace the provider assumptions',['Cost','Amount'],[
   [o.focused_site.public_name,money(o.focused_site.public_price)],[o.plans.keep_running.public_name+': 12 monthly invoices',money(12*o.plans.keep_running.monthly_price)],['Hosting: assumed $20 × 12 months','$240'],['Other provider bills: assumed yearly total','$120'],['First-year total before tax',money(o.focused_site.public_price+12*o.plans.keep_running.monthly_price+360)]
  ])+p('This example assumes care starts at launch and runs for twelve monthly cycles. Replace $20/month hosting and $120/year other bills with your actual renewal prices. Required outside costs are confirmed before booking.')+box('Starting monthly care on an existing website?',p(`The one-time ${money(o.baseline.one_time_price)} Website Baseline comes first unless a previous Website Baseline, studio build or Audit &amp; Fix Sprint still provides a current, usable review. A new studio build does not need a second review of the same work. Work already included in the build is not charged again as monthly care.`))),
  section('redesign-budget','Allow for the work of moving an existing site',p(`Each package includes up to ${o.launch_site.redirect_limit.match(/\d+/)?.[0]||10} simple old-to-new redirects from a list you supply. Finding old pages, planning a large move or resolving complex platform problems needs a separate price.`)+p('List the content and useful page addresses to keep, who controls the old accounts, and which forms or tools need testing after the move. Review the '+a('/guides/website-migration-checklist/','migration checklist')+' and '+a('/guides/website-redesign-timeline/','how long a redesign takes')+' before fixing a launch date.')),
  section('compare-quotes','Give each designer the same brief',p('Use the '+a('/payments/#cost-calculator','cost estimator')+' for studio fees and outside bills. Then try the '+a('/tools/website-roi-calculator/','ROI scenario calculator')+' with your own extra-job and profit assumptions; it is a planning model, not a forecast.')+ul(['Name the customer action you want to make easier.','List the pages, features and writing you need.','Say who will approve the work and edit the site later.','Ask what is included, what costs extra and which provider bills continue.','Check review dates, cancellation terms and the files you receive at handoff.'])+p('Use the '+a('/guides/website-redesign-brief/','redesign brief')+' to compare complete proposals. Read '+a('/pricing/#payments','payment and cancellation terms')+' alongside the price.'))
 ],
 "/guides/website-redesign-brief/":o=>[
  section('before-a-redesign','First, confirm that a redesign is the right job',p(`If you have not yet decided what needs to change, ${a('/guides/website-repair-or-redesign/','compare keeping, fixing, reworking and rebuilding the site')}. This brief helps define a redesign after that earlier decision.`)),
  section('decision','Begin with the decision your customer is making',p('“We need a modern website” is a starting feeling, not yet a project brief. A useful brief says who the website is for, what they need to understand and what they should do next. That gives the design a purpose and makes proposals easier to compare.')+p('For a small service business, the next step might be an estimate request, a phone conversation or a project inquiry. Choose a primary action. Explain what a qualified inquiry looks like so that a form can collect useful details without becoming a long application.')),
  section('business','1. Describe the actual business',ul(['What do you sell, and which one or two service lines matter most?','Who is a good fit, and who is outside the scope?','Where do you deliver the service? Distinguish online work, customer visits and a staffed location.','What should a visitor know before contacting you?','Which claims, qualifications and examples can you support?'])+p('Be specific about geography. Serving customers in Amherst or Hamburg does not imply a public office there. If the business works online, say so. Accurate service information is more useful than a list of town names pasted into every paragraph.')),
  section('content','2. Inventory the content before redesigning it',p('List the current URLs, page titles and purpose of each page. Mark what should remain, what needs rewriting and what can be retired. Identify pages that receive valuable inquiries or search visits before merging them.')+p('Collect approved service facts, the jobs you accept, actual delivery areas, contact and opening details, licensed photographs, and evidence you have permission to share. Add recurring customer questions, mark missing material and name the person responsible for approving changes and keeping each fact current. For a seasonal service, for example, the estimate may depend on property type, the actual route and information needed before booking; the business supplies its own operating facts.')+p(`If URLs will change, use the ${a('/assets/downloads/website-url-map.csv','URL-map worksheet')} and ${a('/guides/website-migration-checklist/','migration checklist')} to map each useful old address to the most relevant new destination.`)),
  section('editing','3. Decide who edits and what the site must do',p('Describe updates in everyday terms: “I change opening hours twice a year,” “our team publishes weekly,” or “prices come from another system.” Those are different requirements. My websites do not include a log-in editing dashboard. You receive full site files and instructions so a developer can make changes, or I can handle small edits through optional care. Tell me before booking if your team needs to edit pages often. Agree who will make, check and publish changes, and how often help will be needed.')+ul(['Does the site need only an inquiry form, or does it need booking or payment?','Will people sign in or view private information?','Does data move into a CRM or another service?','Who maintains integrations and pays the provider bills?','What happens if an external service is unavailable?'])+p('Write required features separately from ideas that would be nice later. That protects the initial project from quietly becoming a different product.')),
  section('acceptance','Decide how you will approve the work',p('Name one approver and realistic review dates. List the pages and forms that must work on a phone and with a keyboard. Ask the developer how the previous version can be restored, and send feedback as one combined list.')+p('Approve the exact website version before launch. At handoff, ask for files, images and licenses, account access, provider renewals and recovery notes. My builds include 30 calendar days of correction for work that does not function as agreed.')+box('A brief you can reuse',p(a('/assets/guides/website-redesign-brief.txt','Download the redesign brief')+' and fill it in with your business facts. It includes questions for each designer.'))+p('See '+a('/assets/audit-implementation/illustrative-completed-brief.txt','a completed fictional brief')+' for an example of how to answer the questions.'))

 ],
 "/guides/local-seo-profile-eligibility/":o=>[
  section('two-surfaces','Your website and your Business Profile have different jobs',p('Local SEO helps a business explain what it offers and where it serves customers. Your website can give that explanation in detail. A Google Business Profile is a separate product with its own eligibility rules. Having a website or serving Buffalo customers does not by itself make a business eligible for a profile.')+p('Google says local results consider relevance, distance and prominence. Useful website work can make services clearer, but it cannot remove the distance between a searcher and a business. No page edit can promise a particular Maps position. See '+a('https://support.google.com/business/answer/7091','Google’s explanation of local ranking')+'.')),
  section('eligibility','Check eligibility before choosing an address',p('Google generally requires eligible businesses to make in-person contact with customers during their stated hours. Online-only businesses are not eligible for a Business Profile. A service-area business that visits customers may qualify under the applicable rules; a studio delivering all work remotely should not assume that it does. Read '+a('https://support.google.com/business/answer/3038177','Google’s business representation guidelines')+' and its '+a('https://support.google.com/business/answer/13763036','eligibility guidance')+'.')+p('For an eligible business that travels to customers and does not serve them at its address, Google instructs it to hide that address. Service areas should describe actual service, not a collection of desirable search locations. Confirm your situation against '+a('https://support.google.com/business/answer/9157481','Google’s service-area instructions')+' before changing the profile.')+box('How I describe my own studio',p('I am based in Buffalo and work online with businesses across '+e(serviceCoverage().region)+'. I do not have a walk-in office or use a virtual-office address to suggest one.'))),
  section('pages','Write pages around the services people need',p('Begin with a clear page for each main service that answers a different customer need. Explain the customer problem, what is included, what changes the price, where the work is delivered and how to inquire. A redesign prospect and an ongoing SEO prospect have different questions, so they deserve clear paths.')+p('For a service business, local detail can be practical: travel boundaries, remote review options, appointment requirements or the information needed for a quote. Use only facts that apply. Copying one page into many town-name versions adds little unless each answers a different customer question.')+p('A useful Erie County service-area page can gather coverage and working arrangements. A separate town page needs a separate reason to exist: genuinely different logistics, service details or supported work examples. A new place name alone is not that reason.')),
  anchoredSection(['local-profile-actions'],section('sequence','Local search steps, in order',ol(['Confirm the real business name, services, coverage, contact details and profile eligibility.','For an eligible profile, use the fewest specific categories that describe the work. Follow the address guidance above.','Keep the website, phone number and customer-facing hours consistent across the profiles you maintain.','Explain each distinct service and check the estimate or inquiry route on a phone.','After real work, invite an honest review without a reward. Reply without exposing customer details.'])+p('See '+a('https://support.google.com/business/answer/3474122','Google’s review guidance')+'. Compare actual search visibility and inquiry quality before deciding what to improve next.'))),
  section('expectations','Buy a defined improvement, then evaluate it',p('Ask what will change on the website, why that is the next priority and how completion will be checked. “More SEO” is too broad to evaluate. A clearer service explanation, repaired internal link and verified inquiry path are concrete work; their commercial effect still needs measurement.')+p(`Explore ${a('/services/seo/','SEO services')}, read the ${a('/areas/erie-county/','Erie County delivery model')}, or ${a('/contact/','discuss the next useful improvement')}.`))

 ],
 "/guides/seo-work-and-reporting/":o=>[
  section('work','Research, finished work and a useful record',p('Good monthly SEO states the research, agreed work, publishing or implementation checks and a record of changes. Measured search results are a separate part of the report.')+p('A list of rankings does not tell you what an SEO service actually did. Useful reporting connects a customer problem, a specific page change, the checks performed and the next decision. Search measurements add context, but they should not replace a record you can check.')+p('For a small service business, the priority may be modest and valuable: explain a service boundary, improve a confusing inquiry step or make an important page easier to find. Agree what will be finished each month so both sides can check it.')),
  section('keyword-opportunities','How keyword opportunities become useful work',p('Start with the real service, the customer question and the action you want a useful page to support. Keyword research can help identify related searches, difficulty estimates and competing content. Search Console and actual customer questions add evidence about the website and business. Record what is available and label what is missing.')+ul(['Investigate relevant lower-competition terms, existing pages with useful impressions, customer questions and seasonal opportunities.','Check actual search results: are people looking for a service, guide, product, map listing or comparison?','Compare competing pages and identify a truthful useful contribution your business can make.','Group close variants around the same need; improve an existing page when it already fits.','Select the page or action, record why it matters and define what finished work will include.'])+p('Keyword tools estimate demand and competition for the area and data selected; they do not predict your Maps position. Record the source, date and geography. A low score for an irrelevant term is not a good business opportunity.')+p('Your opportunity brief should identify the customer question, business fit, available metrics, result-page observations, preferred URL, approved facts and completion test. '+a('/assets/guides/monthly-seo-opportunity-worksheet.csv','Download the monthly opportunity worksheet')+'. No invented keyword figures are supplied in the example.')),
  section('receipt','What a useful monthly report shows',box('Example: rewriting a service page',ul(['<strong>Problem:</strong> visitors cannot tell whether bathroom repairs are offered.','<strong>Work:</strong> rewrite the accepted-job description and add a clear estimate link.','<strong>Checks:</strong> confirm the facts, links, phone layout, keyboard use and form behavior.','<strong>Result record:</strong> link the finished page, give the publication date and note anything still awaiting access.','<strong>Next review:</strong> compare relevant search traffic and suitable inquiries over a stated period.']))+p('This is an illustrative report. For an example from my own website, '+a('/assets/buyer-packs/owned-audit-two-fixes','see two small fixes I made to this website (dated record)')+'.')),
  section('metrics','Read search data in context',p('Search Console reports impressions (times a result appeared), clicks, click-through rate (the share of impressions that led to clicks) and average result position. Filter by the relevant page, search, country, device and period. '+a('https://support.google.com/webmasters/answer/7576553','Google’s Performance report guide')+' explains the measures.')+p('Compare similar periods and note small samples, seasonality and other changes. Count suitable inquiries separately: requests for work you offer, in your service area, with enough detail to reply. Keep names and customer messages out of public reports.')),
  section('scope','Choose the amount of work you can use',ul(monthlyGuidePlanLines(o))+p('An improvement might rewrite a service page, including its search title, links, publication and contact checks. Grow could pair that page with a useful buyer guide. Read '+a('/services/seo/','Improve and Grow limits')+', '+a('/services/website-care/#care-terms','care terms and exclusions')+' and '+a('/pricing/#payments','billing terms')+'.')),
  disclosureSection('campaigns','Grow’s extra promotional piece','See the separate allowance and approval rules',[section('grow-extra','Using approved content',p('Grow’s rolling 90-day plan connects this month’s work with the next customer questions. Its extra promotional piece is a simple graphic in up to three sizes with a caption, or a newsletter excerpt of up to 150 words, using approved content. This is additional to its two main improvements. Posting or sending needs your explicit approval; a new creative concept or email setup needs a separate price.'))]),
  anchoredSection(['timing-and-ai'],section('time','How long before you see results?',p('The finished work has a completion date; search results do not have a guaranteed deadline. Compare a period long enough to include useful data. A new page with a handful of views needs a different review from an established seasonal service.')+p('First check that the promised improvement is live and works. Then use search traffic and suitable inquiries to choose whether to keep it, improve another page or collect more data. For AI-assisted search, follow '+a('https://developers.google.com/search/docs/fundamentals/ai-optimization-guide','Google’s current guidance')+' and keep the page accurate and accessible. An AI mention belongs in the search record, separate from actual customer inquiries.')))

 ],
 "/guides/website-migration-checklist/":o=>[
  section('inventory','Treat a redesign as a move when addresses change',p('A new website can look finished while important old links lead nowhere. If page addresses, domains, content structure or hosting change, plan the move alongside the design. The aim is to preserve useful paths for customers and give search engines clear signals about the new locations. No checklist can guarantee that traffic stays unchanged.')+p('Begin with an inventory of current URLs, downloads, forms and external integrations. Identify the pages that receive meaningful search visits, customer inquiries or links. Keep a recoverable copy of the existing site and a record of who controls the domain, hosting and email settings.')),
  anchoredSection(['redesign-seo-checklist'],section('map','Build an old-to-new URL map',p('List each important old address and the best new destination. Keep addresses unchanged when they still fit. When pages are combined, send the old address to the page covering the same need; do not send every retired page to the home page.')+p('Google’s '+a('https://developers.google.com/search/docs/crawling-indexing/site-move-with-url-changes','site-move guidance')+' explains permanent redirects and temporary search fluctuations during a move.'))),
  section('redirect-example', 'Example URL map', table('Example URL map', ['Old URL', 'New URL', 'Action'], [
      ['/lawn-care', '/services/lawn-care/', 'Permanent redirect to the matching service page.'],
      ['/about/', '/about/', 'Keep the address; no redirect needed.'],
      ['/spring-2023-offer/', 'No replacement', 'Remove obsolete links and show page-not-found if no relevant replacement exists.']
    ]) + `<p>Have the developer check that each redirect reaches the final page in one step. Google recommends keeping redirects for as long as possible, generally at least a year. For a move to a different domain or subdomain, review Search Console’s Change of Address procedure as well. A same-domain path change is a different case. </p><p>${link('/assets/downloads/website-url-map.csv','Download the URL map worksheet')}. Replace its fictional rows with your old addresses, new destinations, owner and checks.</p>`),
  section('before','Before launch: checks for you and your developer','<h3>Your checks</h3>'+ol(['Approve the new service details, photos, contact information and page list.','Open the main pages on a phone; check navigation, downloads and booking links.','Use the <a href="/guides/contact-form-not-working/">form test</a> to confirm a request reaches the business.'])+'<details><summary>Developer checks before switching the live site</summary>'+ol(['Check permanent redirects, page titles, canonical URLs, sitemap and indexing settings. For removed pages with no equivalent replacement, return 404 or 410. Keep private previews out of search.','Record the approved release, destination and way to restore the previous version.','Name the exact DNS changes. Preserve unrelated email records and confirm the mailbox still works.','Test keyboard access, narrow layouts and connected services.'])+'</details>'),
  section('launch','Recheck the live website','<p>After the switch, open the public home, service and contact pages, a useful old link, a download and a missing address. Ask the developer to confirm redirects and missing-page responses. Repeat the contact-form test on the live site and record anything not yet verified.</p>'),
  anchoredSection(['redesign-help'],section('after','Review the move over time',p('Once the new site is open to Google, check it in Search Console. Compare useful periods of search traffic and investigate patterns instead of reacting to one day. If the site is deliberately hidden, missing search results are expected.')+p('A few renamed pages and a major platform move need different amounts of work. The proposal should list retained pages, redirects, account access, email responsibilities and launch checks.')+p(`Each studio build includes up to ${o.launch_site.redirect_limit.match(/\d+/)?.[0]||10} simple old-to-new redirects from the list you supply. Discovering old pages, planning a large move or handling complex redirects is quoted separately. See ${a('/services/website-redesign/','website redesign scope')}.`)))

 ],
 "/guides/custom-website-or-template/":o=>[
  section('fit','Both approaches can work. Fit is the question.',p('A template offers an existing visual and structural starting point. A custom website can organize the experience around the business’s particular story and customer journey. Neither label tells you, by itself, whether a site is clear, fast, accessible or easy to maintain.')+p('For a small business choosing a website, begin with content and operations. What must customers understand? How often will the site change? Who will edit it? What can you invest in the build and in maintaining it? Those answers matter more than how many effects appear in a demo.')),
  section('compare','Compare the same customer journey',`<div class="journal-table-wrap" role="region" tabindex="0" aria-label="Questions to ask of either approach"><table><caption>Questions to ask of either approach</caption><thead><tr><th scope="col">Decision</th><th scope="col">Template starting point</th><th scope="col">Custom direction</th></tr></thead><tbody><tr><th scope="row">Service story</th><td>Does the existing page structure fit your content?</td><td>Can a tailored structure explain the service more clearly?</td></tr><tr><th scope="row">Editing</th><td>Which changes does the included editor support?</td><td>Does the owner need a developer or a separately included page editor to make changes?</td></tr><tr><th scope="row">Distinctive design</th><td>How much can be changed without fragile overrides?</td><td>Which original design decisions matter to the customer?</td></tr><tr><th scope="row">Ongoing cost</th><td>What subscriptions, add-ons and platform limits apply?</td><td>What hosting, provider and maintenance costs remain?</td></tr><tr><th scope="row">Handoff</th><td>What can you export or move to another provider?</td><td>Which paid source, assets and operating notes do you receive?</td></tr></tbody></table></div>`+p('Try a small comparison before committing: use the same service headline, explanation, proof and inquiry fields in each proposed structure. Walk through it on a phone. Notice where the content feels forced, where the next step disappears and which changes require workarounds.')),
  section('template','When a template may be a sensible starting point',p('A template may fit when the service is straightforward, the existing layout supports the content and the team values a familiar editing environment. It can reduce some initial design decisions. Still check the actual plan limits, recurring costs, access controls and export options.')+p('Do not assume that buying a template includes content strategy, copy, photography, migration, form delivery or accessibility review. Those responsibilities exist even when the layout is already drawn. Agree who completes and verifies them.')),
  section('custom','When custom work is useful',p('Custom work may fit when your service story, design or inquiry process needs a structure that a template cannot easily support. Agree what will be designed and built before choosing a package.')+p(`Studio builds are ${money(o.launch_site.public_price)}, ${money(o.focused_site.public_price)} and ${money(o.signature_site.public_price)} for up to 6, 15 and 30 marketing pages. Each includes writing, design, launch and source files. Future changes require coding skills, a developer or optional care; there is no built-in drag-and-drop editor. ${a('/pricing/#website-packages','Compare the full packages')} and tell me how often you need to edit.`)),
  section('quality','Judge the finished experience',ul(['Can a new visitor explain what the business does and who it serves?','Is the primary next step easy to find and complete on a phone?','Can the main journey be used with a keyboard and reduced motion?','Are prices or scope boundaries understandable?','Does the form accept the inquiry and can the owner find it and reply?','Can the owner maintain the site and recover it when needed?'])+p('A useful website explains the offer and lets people complete the next step. Motion can add character when it supports that job; it should pause cleanly and respect reduced-motion preferences.')+p(`Explore ${a('/work/','studio work and explorations')}, read ${a('/services/web-design/','the custom website scope')}, compare ${a('/guides/website-project-cost/','website budget examples')}, or ${a('/contact/','talk through the fit')}.`)),
  ...searchGuideAdditions('/guides/custom-website-or-template/').map(item=>({...item,body:p('A social profile can introduce the business. A website is useful when customers need a stable home for service details, examples, contact information or downloads. Decide what those pages should do before choosing their design.')}))
 ],
 "/guides/website-care-versus-seo/":o=>[
  section('short-answer','Start with the job your website needs',p('Care handles recurring checks and small edits to existing pages. SEO work improves the service explanation so it answers what customers search for. If the problem is still unclear, begin with a one-off review.')+p('Ask who will do the work, what you need to supply and how you will know it is finished. The useful choice follows the task, not the plan name.')),
  section('compare','Compare the work you receive',table('Care and search work',['Work',`Keep Running — ${money(o.plans.keep_running.monthly_price)}/month`,`Improve — ${money(o.plans.improve.monthly_price)} or Grow — ${money(o.plans.grow.monthly_price)}/month` ],[
   ['What changes','One set of small edits to existing text, photos or links you supply.','Keep Running plus one (Improve) or two (Grow) researched improvements.'],['What is checked','Website, contact form, agreed tools and available search or indexing warnings.','The care checks plus the changed page, links and available search data.'],['What you receive','A monthly report and quarterly website check.','The care report plus completed improvements, their checks and the next plan.'],['Not included','New pages, recurring keyword research, unlimited edits or round-the-clock staffing.','Unlimited work or guaranteed rankings, inquiries or AI-search appearances.']
  ])),
  section('situations','Three examples',ul(['<strong>Changed hours:</strong> send the new hours and affected pages. Updating them and checking the phone layout is a small care task.','<strong>Unclear service:</strong> customers cannot tell which repairs you accept. Rewriting that page and checking the estimate route can be one complete improvement.','<strong>Unknown failure:</strong> requests have stopped but you do not know why. Use the '+a('/guides/website-audit-checklist/','audit checklist')+' before buying a recurring campaign.'])),
  section('owned-change','Keep a simple record',p('For each month, record the problem, the change, the page, what was tested and anything left to do. Review actual search traffic and inquiries separately from the completed work.')+p('Use the '+a('/assets/guides/website-care-versus-seo-worksheet.csv','care-or-SEO decision worksheet')+' to choose the task.')),
  section('plans','Compare monthly help',ul(monthlyGuidePlanLines(o))+careBoundary()+p(`Keep Running’s checks continue when no edits are requested. If useful Improve or Grow work and the needed information are not agreed five business days before renewal, the improvement month pauses. We agree in writing whether care also pauses or continues; there is no automatic ${money(o.plans.keep_running.monthly_price)} care charge.`)),
  anchoredSection(['before-buying'],section('costs','Prices and questions to ask',p(`For monthly help on an existing site, start with the ${money(o.baseline.one_time_price)} Website Baseline unless a previous Website Baseline, studio build or Audit &amp; Fix Sprint still provides a current, usable review. Provider bills are separate.`)+ul(['What will be finished this month?','What do I need to send or approve?','What happens if work is delayed or I want to stop?'])+p('Compare '+a('/services/website-care/','care limits')+', '+a('/services/seo/','Improve and Grow limits')+' and '+a('/pricing/#payments','billing and cancellation terms')+'.')))
 ],
 "/guides/website-audit-checklist/":o=>[
  section('start','Choose one visitor task first',p('Start with a task that matters: identify the right service, understand its boundaries or send an inquiry. Write what you expected and what happened. “The site feels dated” is a useful concern to explore; “a phone visitor cannot find the service boundary before the contact form” is a testable finding.')+p(`Still deciding whether the site needs a project at all? Use ${a('/guides/website-repair-or-redesign/','the repair-or-redesign decision guide')} before expanding the scope.`)+p(`Use the ${a('/assets/guides/website-audit-checklist.csv','audit checklist (CSV)')} to record what you checked, the result, evidence, any fix and the next check. The worksheet starts at “Not checked.” Use Works, Needs fixing, Need access, Not applicable or Blocked after checking. Explain a blocked check and name the person who can resolve it. Keep screenshots and records free of passwords, customer messages and other private information.`)),
  section('checklist','Check the tasks a customer relies on',ol(['Can you tell what the business offers and whether your job fits?','Can you read the important pages and use the menu on a phone and with a keyboard?','Do prices, contact details, service areas and links agree across the site?','Can you send an inquiry and receive a reply? Use the <a href="/guides/contact-form-not-working/">form test</a> for the full procedure.','Ask your developer to check indexing, page titles, speed, accessibility findings and a way to recover the site. Record unavailable access instead of guessing a pass.'])),
  section('priority','Choose a small correction',p('Prioritize the problem that stops customers completing the main task. Record what happened, which page needs to change and what a successful retest looks like.')+p('Keep a recoverable copy before editing. After the change, repeat the original task and check nearby links and behavior. Automated checks can support that test; they cannot replace trying the task.')),
  section('owned-fixes','Example: the form says “sent”, but no email arrives',box('Illustrative contact-form check',p('<strong>Check:</strong> send a message with made-up details and look for it in the form tool’s saved submissions. Check which email address receives notifications.')+p('<strong>Fix:</strong> if the saved message exists and the recipient is an old address, correct that address with the owner’s approval. Other findings need a different fix.')+p('<strong>Finish:</strong> send another test, confirm that it reaches the inbox and reply to your test address.'))+p('This example is hypothetical. '+a('/assets/buyer-packs/owned-audit-two-fixes','Example: two small fixes to this website')+' shows separate work on my own site.')),
  section('access','Use “needs access” when you cannot test',p('Public pages let you inspect copy, links and many layout or keyboard behaviors. Search Console, analytics, form storage, notification logs, account ownership and restore operations may require authorized access. Mark those checks “needs access” with a named owner and next step; do not turn a missing account into a pass or a guessed diagnosis.')+p('A live form test can create a record or send a notification. Agree the test destination and made-up test details before submitting, then distinguish the browser confirmation, stored record and actual delivery. Recovery tests need a safe environment and an agreed rollback procedure.')+p('Real users, assistive technology and physical devices can expose problems a scanner misses. If a task needs specialist investigation, record the boundary and commission the appropriate review instead of promising that a general website audit covers it.')),
  section('finish','Finish with a dated record and the next decision',ul(['Link the original finding and its evidence date.','State the approved fix and the exact changed page or component.','Record the retest method, result, environment and unresolved limitation.','Name the owner of the remaining issue and the next decision.'])+guideReviewChoices(o)+p(`For search-only questions, see ${a('/services/seo/','the SEO scope')}. For a larger redesign, prepare ${a('/guides/website-redesign-brief/','a clear project brief')}.`))
 ],
 "/guides/website-repair-or-redesign/":o=>[
  section('start','Begin with the problem, not the age of the site',p('An older website may work well, and a new one may make a customer’s next step difficult. Start with the task: understand a service, check your coverage or send an inquiry. Write what should happen and what actually happens.')+p('A changed service, repeated customer question or new editing need may justify a project. A new town name or visual preference alone does not show that you need more pages.')+p('Use the '+a('/guides/website-audit-checklist/','audit checklist')+' to record a failure. If a redesign is already justified, prepare the '+a('/guides/website-redesign-brief/','redesign brief')+'.')),
  section('keep','Keep what already does the job',p('Keep the current site when its important visitor tasks work, its content matches the business and the ownership and operating arrangements are sound. A clear, maintainable site does not need a new project simply because another design is fashionable.')+p('Record what is worth retaining: accurate service copy, useful URLs, licensed images, recognizable identity, working forms and client-owned accounts. Also identify who can edit, export and recover the site. If those answers are missing, mark them as unresolved; do not assume that either a patch or a rebuild removes the risk.')+p('Doing nothing is fine if the site works. Recheck when your services change, customers keep asking the same question or you need an editing feature the site cannot provide.')),
  section('contained','Choose a small fix when the problem is clear',p('A small correction makes sense when you know the affected page or feature, have the access to change it and can test the result. A wrong button destination or missing label may fit. An unexplained failure across several tools needs investigation first.')+ul(['Name the page or feature to change.','Ask your web person to check the platform, account access and a way to undo the change.','Describe the customer task you will repeat afterward.','Record any remaining problem and who will handle it.'])+p('I do not offer emergency fixes or hacked-site recovery. For WordPress, Wix, Squarespace and other platforms, I check your setup and access before quoting.')),
  section('owned','Two small repairs to try before a rebuild',box('Illustrative examples',`<ol><li><strong>A broken inquiry route.</strong> A garden-care page sends every button to the home page. Point the estimate button to the correct form, preserve the selected service and check the phone and keyboard path.</li><li><strong>An unclear offer.</strong> A repair service mixes included work and exclusions in one list. Separate them so a customer can tell whether the job fits before asking for a quote.</li></ol>`)+p(`Both examples assume the existing site and access support a small change. ${a('/assets/buyer-packs/owned-audit-two-fixes','See two real fixes I made to my own website')}: a clearer exclusions list and a contact form that remembers the chosen service.`)),
  section('rework','When broader changes or a rebuild make sense',p('Rework can make sense when the existing system remains suitable but its content or page structure no longer explains the business. Consider rebuilding when the current site cannot reasonably meet the agreed requirements. Establish which constraint is real before selecting a new platform; a visual preference and an operational limit are different reasons for change.')+box('Hypothetical scenario — not a client project',p('A service business now needs several distinct service journeys and frequent publishing by a nontechnical editor. Its current one-page static setup has no editing workflow that meets those requirements. First check whether supported changes to the current setup could provide the needed structure and editing. If they cannot, scope a rebuild with retained content, useful URLs, account ownership and migration checks. This scenario does not imply a quoted cost, saving or completion date.'))+p('Changing the platform creates work of its own: content transfer, redirects where needed, form and tool checks, editing training and a recovery route. Include those responsibilities in the comparison; a new design does not automatically complete them.')),
  section('compare','Compare what will work when the job is finished',p('Ask each proposed approach to explain the same things: the customer task it fixes, useful content and accounts it keeps, required changes, outside bills and any problem left unresolved. Choose from those answers, not only the lowest price.')+guideReviewChoices(o)+p('Use the '+a('/guides/website-project-cost/','budget guide')+' for cost components. The proposal sets dates around the facts, account access and reviews the work needs.')),
  section('worksheet','Write down the decision before booking work',p('The '+a('/assets/guides/website-repair-or-redesign-worksheet.csv','repair-or-redesign worksheet')+' records the problem, what you saw, content and accounts to keep, access, a possible fix and its retest. Replace the fictional example with your own website.')+p('Choose a next step: keep the site, fix one problem, investigate an unknown failure or prepare a redesign brief. If access or facts are missing, name who can provide them before deciding.'))

 ]
};

export function guideContentSections(path,offers){
 const authored=floridaGuideContent[path]||operatingGuideContent[path]||longtailGuideContent[path]||researchGuideContent[path];
 return formatGuideSections(expandLongtailSections(path,withFloridaGuideExamples(path,[...(typeof authored==='function'?authored(offers):authored||guideContent[path]?.(offers)||[]),...(researchGuideExpansions[path]||[])])));
}
